public class GameObject:Object {public int layer; public bool activeSelf=true; public bool activeInHierarchy=>activeSelf&&(transform.parent==null||transform.parent.gameObject.activeInHierarchy); public Transform transform; private Dictionary<Type,Component> c=new(); public GameObject(string name,params Type[] types){this.name=name; transform=Array.IndexOf(types,typeof(RectTransform))>=0?new RectTransform():new Transform();transform.gameObject=this;c[transform.GetType()]=transform;foreach(var t in types)if(t!=typeof(RectTransform))AddComponent(t);}public T AddComponent<T>() where T:Component,new()=> (T)AddComponent(typeof(T));private Component AddComponent(Type t){var v=(Component)Activator.CreateInstance(t);v.gameObject=this;c[t]=v;return v;}public T GetComponent<T>() where T:Component {foreach(var v in c.Values)if(v is T t)return t;return null;}public void SetActive(bool a){activeSelf=a;}}
public class Transform:Component {public Transform parent;public Vector3 localPosition;public Quaternion localRotation=Quaternion.identity;public Vector3 localScale=Vector3.one;public Vector3 position {get=>parent==null?localPosition:parent.TransformPoint(localPosition);set=>localPosition=value-(parent==null?Vector3.zero:parent.position);} public Quaternion rotation{get=>localRotation;set=>localRotation=value;}public Vector3 right=>Vector3.right;public void SetParent(Transform p,bool world=false){parent=p;}public void LookAt(Vector3 p){}public Vector3 TransformPoint(Vector3 p)=>position+new Vector3(p.x*localScale.x,p.y*localScale.y,p.z*localScale.z);}
