public static class Mathf{public const float PI=MathF.PI,Rad2Deg=180/MathF.PI;public static float Sin(float a)=>MathF.Sin(a);public static float Cos(float a)=>MathF.Cos(a);public static float Atan2(float y,float x)=>MathF.Atan2(y,x);public static float Sqrt(float x)=>MathF.Sqrt(x);public static int CeilToInt(float x)=>(int)MathF.Ceiling(x);public static int RoundToInt(float x)=>(int)MathF.Round(x);public static float Abs(float x)=>MathF.Abs(x);public static float Min(params float[] x){float y=float.MaxValue;foreach(var a in x)y=MathF.Min(y,a);return y;}public static float Max(float a,float b)=>MathF.Max(a,b);public static int Max(int a,int b)=>Math.Max(a,b);public static float Clamp(float a,float lo,float hi)=>Math.Clamp(a,lo,hi);public static int Clamp(int a,int lo,int hi)=>Math.Clamp(a,lo,hi);public static float Clamp01(float a)=>Clamp(a,0,1);public static float Lerp(float a,float b,float t)=>a+(b-a)*Clamp01(t);public static float InverseLerp(float a,float b,float x)=>Clamp01((x-a)/(b-a));}
